/**
 * The planets a save is refused for (ticket 888, the TD's storage row): a planet stamped with ore
 * rules newer than this build's was generated by a later build, so this build could not make its
 * cells again, and the save is refused, never regenerated. Read off the file as saved, before any
 * step of the migration chain, so the refusal names the stamp the file holds: the planet the world
 * section is on and every left planet's stamp, as `ore_rules_refused {system, place, oreRulesVersion}`.
 */
import { isJsonObject } from '../authority/payloadFields'
import { newerAwayStampsOf } from '../authority/planetOreStamps'
import { placeOfCampaign } from '../starMap/campaignIndex'
import { FIRST_SYSTEM, readIndexText, toIndexText } from '../starMap/planetAddress'
import { isKnownOreRulesVersion } from '../world/planetParams'

/** A planet the save holds under ore rules this build does not know, by its address. */
export interface RefusedOreRules {
  system: string
  place: string
  oreRulesVersion: number
}

/** Every planet of the save file stamped newer than this build; empty when there is none. */
export function refusedOreRulesOfSave(file: unknown): RefusedOreRules[] {
  if (!isJsonObject(file) || !isJsonObject(file.world)) return []
  const { world } = file
  return [...refusedSavedPlanetOf(world), ...refusedAwayPlanetsOf(world.awayOreRules)]
}

function refusedSavedPlanetOf(world: Record<string, unknown>): RefusedOreRules[] {
  const stamp = world.oreRulesVersion
  if (typeof stamp !== 'number' || isKnownOreRulesVersion(stamp)) return []
  if (typeof world.planetIndex !== 'number' || !Number.isSafeInteger(world.planetIndex)) return []
  const system = readIndexText(world.system) ?? FIRST_SYSTEM
  const place = placeOfCampaign(system, BigInt(world.planetIndex))
  return [{ system: toIndexText(system), place: toIndexText(place), oreRulesVersion: stamp }]
}

/** A left planet's key is `s:p` (`corePlanetKeyOf`). */
function refusedAwayPlanetsOf(stamps: unknown): RefusedOreRules[] {
  return newerAwayStampsOf(stamps).map(({ key, oreRulesVersion }) => {
    const [system, place] = key.split(':')
    return { system, place, oreRulesVersion }
  })
}
